import torch; import numpy as np; base=r'c:\Users\Gebruiker\Documents\Computational Bio\diffusion-cryoem-prior'; import sys; import os; sys.path.append(base); from models.unet_3d import UNet3D; from models.diffusion import DiffusionModel; from data.volume_dataset import VolumeDataset; from projection.radon import RadonProjector; from scripts.verify_volume_reconstruction import reconstruct_volume_dps; device=torch.device('cuda'); net=UNet3D(in_ch=1,out_ch=1,time_dim=64); model=DiffusionModel(net, 1000).to(device); model.load_state_dict(torch.load(os.path.join(base,'experiments','checkpoints','ddpm_volume_overfit.pth'), map_location=device)); model.eval(); data_dict=torch.load(os.path.join(base,'data','processed','cath_subset.pt'), weights_only=False); coords=data_dict['1hel']*10.0; coords=coords-coords.mean(dim=0,keepdim=True); vol_gt=VolumeDataset.voxelize_gaussian(coords,64,1.0,1.0).to(device).unsqueeze(0).unsqueeze(0); projector=RadonProjector(64).to(device); R=projector.random_rotation_matrix(3,device=device); y_meas=projector(vol_gt.repeat(3,1,1,1,1),R); vol_rec=reconstruct_volume_dps(model,projector,y_meas,R,device,step_scale=2.0); v_rec=vol_rec[0,0].cpu().numpy(); print('Min:', v_rec.min(), 'Max:', v_rec.max(), 'Mean:', v_rec.mean()); print('99th:', np.percentile(v_rec, 99), '95th:', np.percentile(v_rec, 95))  
